define(["core/ajax","core/templates","core/str","core/notification","core/modal"],function(Ajax,Templates,Str,Notification,Modal){const init=()=>{document.addEventListener("click",async event=>{const trigger=event.target.closest(".view-reminder-details");if(!trigger){return}event.preventDefault();const userid=Number(trigger.dataset.userid);const courseid=Number(trigger.dataset.courseid);try{const records=await Ajax.call([{methodname:"local_coursereminder_mails_get_reminder_history",args:{userid:userid,courseid:courseid}}])[0];const context={hasrecords:records.length>0,records:records.map(record=>({type:record.type,day:record.day,timesent:record.timesent,sent:Number(record.status)===1}))};const{html:html,js:js}=await Templates.renderForPromise("local_coursereminder_mails/reminder_history",context);Templates.runTemplateJS(js);const title=await Str.get_string("reminderhistory","local_coursereminder_mails");const modal=await Modal.create({title:title,body:html});modal.show()}catch(error){Notification.exception(error)}});document.addEventListener("change",event=>{if(event.target.matches("#selectall")){document.querySelectorAll(".selectitem").forEach(checkbox=>{checkbox.checked=event.target.checked})}})};return{init:init}});